package com.muthumol.player.dummy;
final class TelegramSessions {
 static void show(MainActivity a){a.session.tasks.execute(()->{try{Object response=a.tg.waitRequest("GetActiveSessions");Object sessions=TelegramBridge.get(response,"sessions");if(!(sessions instanceof Object[]))throw new Exception(TelegramBridge.str(response,"message"));Object[] items=(Object[])sessions;String[] labels=new String[items.length];for(int i=0;i<labels.length;i++)labels[i]=(TelegramBridge.bool(items[i],"isCurrent")?"This session · ":"")+TelegramBridge.str(items[i],"deviceModel")+" · "+TelegramBridge.str(items[i],"applicationName")+" · "+TelegramBridge.str(items[i],"platform");a.runOnUiThread(()->Ui.menu(a,"Signed-in Telegram sessions",labels,n->{Object session=items[n];if(TelegramBridge.bool(session,"isCurrent")){Ui.message(a,"This session","This is the running app session.");return;}Ui.dialog(a).setTitle("End this session?").setMessage(labels[n]).setPositiveButton("End session",(d,w)->terminate(a,TelegramBridge.num(session,"id"))).setNegativeButton("Keep",null).show();}));}catch(Exception e){a.runOnUiThread(()->Ui.message(a,"Sessions",e.getMessage()));}});}
 static void terminate(MainActivity a,long id){a.session.tasks.execute(()->{String message;try{Object result=a.tg.waitRequest("TerminateSession","sessionId",id);message=TelegramBridge.type(result).equals("Error")?TelegramBridge.str(result,"message"):"Session ended.";}catch(Exception e){message="Could not end session · "+e.getMessage();}String result=message;a.runOnUiThread(()->Ui.message(a,"Session",result));});}
}
